#include <vector>
#include <fstream>
#include <cstdint>
#include <cstddef>
#include <cstring>
#include <cmath>
#include <chrono>
#define main historical_main_prototype
#include "../lavaMD-cuda/main.h"
#undef main
#include "../lavaMD-cuda/kernel.h"
static_assert(sizeof(box_str)==656&&sizeof(nei_str)==24&&sizeof(FOUR_VECTOR)==16,"source ABI");
static_assert(offsetof(box_str,offset)==16&&offsetof(box_str,nn)==24&&offsetof(box_str,nei)==32&&offsetof(nei_str,number)==12,"source field ABI");
using U=uint64_t;const U MSENT=0xdeadbeef12345678ULL;const float FSENT=-8192.25f;
void ck(cudaError_t e){if(e!=cudaSuccess){fprintf(stderr,"%s\n",cudaGetErrorString(e));exit(2);}}
std::vector<double>load(const char*path){std::ifstream f(path,std::ios::binary|std::ios::ate);size_t n=size_t(f.tellg());std::vector<double>a(n/8);f.seekg(0);f.read((char*)a.data(),n);return a;}
struct Case{int B,mode,np,nb;float alpha;std::vector<U>mh;std::vector<float>rh,qh;U*m;float*r,*q,*out;};
void run(Case&c){md<<<c.nb,128>>>((const box_str*)(c.m+4),(const FOUR_VECTOR*)(c.r+4),c.q+4,(FOUR_VECTOR*)(c.out+4),c.alpha,c.nb);ck(cudaGetLastError());}
int main(){auto f=load(LAVA_FIXTURE),oracle=load(LAVA_ORACLE),budget=load(LAVA_BUDGET);size_t pos=0;std::vector<Case>cases;while(pos<f.size()){Case c;c.B=int(f[pos++]);c.nb=c.B*c.B*c.B;c.mode=int(f[pos++]);c.alpha=float(f[pos++]);c.np=int(f[pos++]);int mw=int(f[pos++]);std::vector<uint32_t>words(mw);for(int i=0;i<mw;i++)words[i]=uint32_t(f[pos++]);c.mh.assign(mw/2+8,MSENT);memcpy(c.mh.data()+4,words.data(),mw*4);c.rh.assign(4*c.np+8,FSENT);for(int i=0;i<4*c.np;i++)c.rh[i+4]=float(f[pos++]);c.qh.assign(c.np+8,FSENT);for(int i=0;i<c.np;i++)c.qh[i+4]=float(f[pos++]);ck(cudaMalloc(&c.m,c.mh.size()*8));ck(cudaMalloc(&c.r,c.rh.size()*4));ck(cudaMalloc(&c.q,c.qh.size()*4));ck(cudaMalloc(&c.out,c.rh.size()*4));ck(cudaMemcpy(c.m,c.mh.data(),c.mh.size()*8,cudaMemcpyHostToDevice));ck(cudaMemcpy(c.r,c.rh.data(),c.rh.size()*4,cudaMemcpyHostToDevice));ck(cudaMemcpy(c.q,c.qh.data(),c.qh.size()*4,cudaMemcpyHostToDevice));ck(cudaMemcpy(c.out,c.rh.data(),c.rh.size()*4,cudaMemcpyHostToDevice));cases.push_back(c);}
for(auto&c:cases){ck(cudaMemset(c.out+4,0,4*c.np*4));run(c);ck(cudaDeviceSynchronize());}
for(int trial=1;trial<=5;trial++){auto payload=f;bool ok=true;size_t oi=0;double elapsed=0,maxerr=0,maxratio=0;std::vector<double>times,imbalances;for(auto&c:cases){std::vector<float>fb(4*c.np+8,FSENT);ck(cudaMemcpy(c.out,fb.data(),fb.size()*4,cudaMemcpyHostToDevice));ck(cudaMemset(c.out+4,0,4*c.np*4));ck(cudaDeviceSynchronize());auto start=std::chrono::steady_clock::now();run(c);ck(cudaDeviceSynchronize());double t=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count();times.push_back(t);elapsed+=t;std::vector<U>mb(c.mh.size());std::vector<float>rb(c.rh.size()),qb(c.qh.size());ck(cudaMemcpy(mb.data(),c.m,mb.size()*8,cudaMemcpyDeviceToHost));ck(cudaMemcpy(rb.data(),c.r,rb.size()*4,cudaMemcpyDeviceToHost));ck(cudaMemcpy(qb.data(),c.q,qb.size()*4,cudaMemcpyDeviceToHost));ck(cudaMemcpy(fb.data(),c.out,fb.size()*4,cudaMemcpyDeviceToHost));ok&=mb==c.mh&&memcmp(rb.data(),c.rh.data(),rb.size()*4)==0&&memcmp(qb.data(),c.qh.data(),qb.size()*4)==0;for(int i=0;i<4;i++)ok&=fb[i]==FSENT&&fb[4*c.np+4+i]==FSENT;std::vector<uint32_t>mwords(mb.size()*2);memcpy(mwords.data(),mb.data(),mb.size()*8);for(auto v:mwords)payload.push_back(double(v));for(auto v:rb)payload.push_back(double(v));for(auto v:qb)payload.push_back(double(v));for(auto v:fb)payload.push_back(double(v));double total=0;for(int i=0;i<c.np;i++)total+=c.qh[i+4];for(int i=0;i<4*c.np;i++){double value=double(fb[i+4]),e=fabs(value-oracle[oi+i]);maxerr=fmax(maxerr,e);maxratio=fmax(maxratio,e/budget[oi+i]);ok&=std::isfinite(value)&&e<=budget[oi+i];if(c.mode==0)ok&=value==(i%4==0?total:0.);}for(int axis=1;axis<=3;axis++){double imbalance=0,allow=1e-9;for(int i=0;i<c.np;i++){imbalance+=double(c.qh[i+4])*double(fb[4*i+axis+4]);allow+=fabs(double(c.qh[i+4]))*budget[oi+4*i+axis];}imbalances.push_back(fabs(imbalance));ok&=fabs(imbalance)<=allow;}oi+=4*c.np;}
std::string path="trial_"+std::to_string(trial)+".bin";std::ofstream out(path,std::ios::binary);out.write((char*)payload.data(),payload.size()*8);out.close();printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.17g,\"correct\":%s,\"checked_values\":%zu,\"max_abs_error\":%.17g,\"max_forward_error_budget_ratio\":%.17g,\"weighted_force_imbalances\":[",trial,elapsed,ok?"true":"false",payload.size(),maxerr,maxratio);for(size_t i=0;i<imbalances.size();i++)printf("%s%.17g",i?",":"",imbalances[i]);printf("],\"timing_region\":\"sum3_lavaMD_original_single_kernel_complete\",\"jit_excluded\":true,\"internal_repeats\":1,\"timed_kernel_calls\":3,\"case_times_seconds\":[");for(size_t i=0;i<times.size();i++)printf("%s%.17g",i?",":"",times[i]);printf("],\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"float64\",\"count\":%zu,\"byte_order\":\"little\"}}\n",path.c_str(),payload.size());if(!ok)return 3;}
for(auto&c:cases){ck(cudaFree(c.m));ck(cudaFree(c.r));ck(cudaFree(c.q));ck(cudaFree(c.out));}}
